#!/usr/bin/env python3
"""Independent clipboard copies, dependency graphs and transactional rollback."""
import importlib.util,pathlib,unittest,json,subprocess,base64
HERE=pathlib.Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('copy_harness',HERE/'smoke.py');h=importlib.util.module_from_spec(spec);spec.loader.exec_module(h)
def p(t):return {'type':'paragraph','content':[{'type':'text','text':t}]}
def gallery(ids,**attrs):return {'type':'gallery','attrs':dict(manual=True,pageIds=ids,title='Galerie',columns=3,rows=2,aspect='1/1',layout='grid',**attrs)}
class Copy(unittest.TestCase):
 @classmethod
 def setUpClass(cls):h.Integration.setUpClass();cls.admin=h.Integration.admin;cls.visitor=h.Integration.visitor
 @classmethod
 def tearDownClass(cls):h.Integration.tearDownClass()
 def ok(self,r,status=200):self.assertEqual(r[0],status,r[1]);return r[1]
 def page(self,title,blocks=None,**kw):return self.ok(self.admin.api('save',dict(title=title,content={'type':'doc','content':blocks or [p('Texte')]},**kw)))['page']
 def current(self,page):return self.ok(self.admin.api('page',query='&id='+page['id']))['page']
 def paste(self,target,blocks,paths=None,**extra):
  return self.admin.api('blocks_copy',dict(id=target['id'],version=target['version'],content={'type':'doc','content':blocks},paths=paths or [[i] for i in range(len(blocks))],**extra))
 def pages(self):return self.ok(self.admin.api('pages'))['pages']
 def test_01_gallery_pages_and_children_are_new_and_independent_both_ways(self):
  a=self.page('A',[p('Source A')]);child=self.page('Sous-page',[p('Source enfant')],parent_id=a['id']);b=self.page('B',[p('Source B')]);target=self.page('Destination');originals={x['id']:self.current(x) for x in [a,b,child]};result=self.ok(self.paste(target,[gallery([a['id'],b['id']])]))
  copy=result['page']['content']['content'][0];ids=copy['attrs']['pageIds'];self.assertEqual(result['copied']['pages'],3);self.assertTrue(set(ids).isdisjoint(originals));self.assertEqual(copy['attrs']['columns'],3)
  new_a=self.current({'id':ids[0]});self.assertEqual(new_a['parent_id'],target['id']);self.assertEqual(new_a['content'],a['content']);new_child=next(x for x in self.pages() if x['parent_id']==new_a['id']);self.assertNotIn(new_child['id'],originals);self.assertEqual(self.current(new_child)['content'],child['content'])
  self.ok(self.admin.api('save',{**new_a,'title':'Copie renommée','content':{'type':'doc','content':[p('Copie modifiée')]}}));self.assertEqual(self.current(a),originals[a['id']]);self.ok(self.admin.api('save',{**b,'title':'Original renommé'}));self.assertEqual(self.current({'id':ids[1]})['title'],'B');self.assertEqual(self.current(child),originals[child['id']])
 def test_02_repeated_paste_and_existing_target_reference_not_rewritten(self):
  source=self.page('Unique');target=self.page('Cible');g=gallery([source['id']]);r=self.ok(self.paste(target,[g,g],paths=[[1]]));blocks=r['page']['content']['content'];self.assertEqual(blocks[0],g);self.assertNotEqual(blocks[1]['attrs']['pageIds'],g['attrs']['pageIds']);r2=self.ok(self.paste(r['page'],[g]));self.assertTrue(set(r2['page']['content']['content'][0]['attrs']['pageIds']).isdisjoint(blocks[1]['attrs']['pageIds']))
 def test_03_file_bytes_name_cover_and_icon_are_copied(self):
  f=self.ok(self.admin.upload('upload','Original.txt',b'Keep original bytes','text/plain'))['file'];img=self.ok(self.admin.upload('upload','Pixel.png',base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Wl6xZ0AAAAASUVORK5CYII='),'image/png'))['file']
  a=self.page('Avec fichier',[{'type':'fileBlock','attrs':dict(fileId=f['id'],name=f['name'],mime=f['mime'],mode='download')}],cover_id=img['id'],icon_id=img['id']);target=self.page('Destination');r=self.ok(self.paste(target,[gallery([a['id']]),{'type':'fileBlock','attrs':dict(fileId=f['id'],name=f['name'],mime=f['mime'],mode='download')}]));new_a=self.current({'id':r['page']['content']['content'][0]['attrs']['pageIds'][0]});new_f=r['page']['content']['content'][1]['attrs']['fileId'];self.assertNotEqual(new_f,f['id']);self.assertEqual(new_a['content']['content'][0]['attrs']['fileId'],new_f);self.assertEqual(new_a['cover_id'],new_a['icon_id']);self.assertNotEqual(new_a['cover_id'],img['id']);self.assertEqual(r['copied']['files'],2)
  self.ok(self.admin.api('rename_file',{'id':new_f,'name':'Copie.txt'}));self.assertEqual(self.ok(self.admin.api('file_info',query='&id='+f['id']))['file']['name'],'Original.txt');self.assertEqual(self.ok(self.admin.request('media.php?id='+new_f)),b'Keep original bytes');self.ok(self.visitor.request('media.php?id='+new_f),404)
 def test_04_cycles_dedup_and_internal_links_are_remapped(self):
  a=self.page('Parent');b=self.page('Enfant',parent_id=a['id']);b=self.ok(self.admin.api('save',{**b,'content':{'type':'doc','content':[{'type':'pageLink','attrs':{'pageId':a['id']}},{'type':'paragraph','content':[{'type':'text','text':'Retour','marks':[{'type':'link','attrs':{'href':self.admin.base+'/index.php?page='+a['slug']}}]}]}]}}))['page'];target=self.page('Destination');r=self.ok(self.paste(target,[gallery([b['id'],a['id']]),{'type':'pageLink','attrs':{'pageId':a['id']}}]));ids=r['page']['content']['content'][0]['attrs']['pageIds'];self.assertEqual(r['copied']['pages'],2);copied_b=self.current({'id':ids[0]});copied_a=self.current({'id':ids[1]});self.assertEqual(copied_a['parent_id'],target['id']);self.assertEqual(copied_b['parent_id'],copied_a['id']);self.assertEqual(copied_b['content']['content'][0]['attrs']['pageId'],copied_a['id']);self.assertEqual(copied_b['content']['content'][1]['content'][0]['marks'][0]['attrs']['href'],self.admin.base+'/index.php?page='+copied_a['id']);self.assertEqual(r['page']['content']['content'][1]['attrs']['pageId'],copied_a['id'])
 def test_05_legacy_gallery_is_frozen_and_empty_stays_empty(self):
  parent=self.page('Source de la vue');a=self.page('Un enfant',parent_id=parent['id']);target=self.page('Destination');g={'type':'gallery','attrs':{'manual':False,'parentId':parent['id'],'kind':'page','columns':4}};r=self.ok(self.paste(target,[g],source_id=parent['id']));attrs=r['page']['content']['content'][0]['attrs'];self.assertTrue(attrs['manual']);self.assertEqual(attrs['parentId'],'');self.assertEqual(attrs['kind'],'');self.assertEqual(len(attrs['pageIds']),1);self.assertNotEqual(attrs['pageIds'][0],a['id']);self.page('Ajout original',parent_id=parent['id']);self.assertEqual(self.current(r['page'])['content']['content'][0]['attrs']['pageIds'],attrs['pageIds']);r2=self.ok(self.paste(self.current(r['page']),[gallery([])]));self.assertEqual(r2['copied']['pages'],0);self.assertEqual(r2['page']['content']['content'][0]['attrs']['pageIds'],[])
 def test_06_auth_csrf_and_methods(self):
  self.ok(self.visitor.api('blocks_copy',{}),401);self.ok(self.admin.api('blocks_copy',{},authenticated=False),403);self.ok(self.admin.api('blocks_copy'),405)
 def test_07_invalid_paths_conflicts_and_rollback_do_not_create_entities(self):
  target=self.page('Cible');a=self.page('À garder');before=len(self.pages());g=gallery([a['id']]);r=self.paste(target,[g],version=0) if False else self.admin.api('blocks_copy',dict(id=target['id'],version=0,content={'type':'doc','content':[g]},paths=[[0]]));self.ok(r,409)
  self.ok(self.paste(target,[g],paths=[[9]]),400);self.ok(self.paste(target,[gallery([a['id'],'00000000-0000-4000-8000-000000000000'])]),409);self.assertEqual(len(self.pages()),before);self.assertEqual(self.current(target),target)
 def test_08_database_relations_forms_and_rows_have_new_ids(self):
  db=self.ok(self.admin.api('db_save',{'name':'Table A'}))['database'];title=self.ok(self.admin.api('property_save',{'db_id':db['id'],'name':'Nom','type':'title','config':{}}))['property'];row=self.ok(self.admin.api('row_save',{'db_id':db['id'],'values':{title['id']:'Original'}}))['row'];rel=self.ok(self.admin.api('property_save',{'db_id':db['id'],'name':'Lien','type':'relation','config':{'target_db_id':db['id']}}))['property'];row=self.ok(self.admin.api('row_save',{'id':row['id'],'version':row['version'],'db_id':db['id'],'values':{title['id']:'Original',rel['id']:[row['id']]}}))['row'];form=self.ok(self.admin.api('form_save',{'db_id':db['id'],'name':'Formulaire','fields':[title['id']],'public':True}))['form'];target=self.page('Cible');blocks=[{'type':'databaseView','attrs':{'dbId':db['id'],'viewConfig':{'layout':'gallery','hiddenPropertyIds':[rel['id']]}}},{'type':'formView','attrs':{'formId':form['id']}}];r=self.ok(self.paste(target,blocks));new_id=r['page']['content']['content'][0]['attrs']['dbId'];self.assertNotEqual(new_id,db['id']);data=self.ok(self.admin.api('db_get',query='&id='+new_id));new_title=next(p for p in data['properties'] if p['type']=='title');new_rel=next(p for p in data['properties'] if p['type']=='relation');self.assertEqual(new_rel['config']['target_db_id'],new_id);self.assertNotEqual(data['rows'][0]['id'],row['id']);self.assertEqual(data['rows'][0]['values'][new_rel['id']],[data['rows'][0]['id']]);self.assertEqual(r['page']['content']['content'][0]['attrs']['viewConfig']['hiddenPropertyIds'],[new_rel['id']]);new_form=data['forms'][0];self.assertEqual(r['page']['content']['content'][1]['attrs']['formId'],new_form['id']);self.assertNotEqual(new_form['token'],form['token']);self.assertFalse(new_form['public']);self.assertEqual(new_form['fields'],[new_title['id']]);self.ok(self.admin.api('row_patch',dict(id=data['rows'][0]['id'],version=data['rows'][0]['version'],property_id=new_title['id'],value='Copie')));self.assertEqual(self.ok(self.admin.api('db_get',query='&id='+db['id']))['rows'][0]['values'][title['id']],'Original')
 def test_09_publication_policy_and_original_untouched(self):
  self.ok(self.admin.api('settings',{'notebook':{'auto_publish':True,'auto_publish_children':True}}));a=self.page('Original privé');target=self.page('Destination publique');self.ok(self.admin.api('publish',{'id':target['id'],'version':target['version']}));r=self.ok(self.paste(self.current(target),[gallery([a['id']])]));new_id=r['page']['content']['content'][0]['attrs']['pageIds'][0];self.ok(self.visitor.api('page',query='&id='+new_id));self.ok(self.visitor.api('page',query='&id='+a['id']),404);self.assertEqual(self.current(a)['visibility'],'private');self.ok(self.admin.api('settings',{'notebook':{'auto_publish':True,'auto_publish_children':False}}))
 def test_10_quiz_identifiers_are_new(self):
  quiz={'type':'quiz','attrs':{'quizId':'old-quiz','questions':[{'id':'old-q','type':'short','prompt':'Question','options':[],'correct':[],'answers':['Réponse']}]}};r=self.ok(self.paste(self.page('Destination'),[quiz]));a=r['page']['content']['content'][0]['attrs'];self.assertNotEqual(a['quizId'],'old-quiz');self.assertNotEqual(a['questions'][0]['id'],'old-q');self.assertEqual(a['questions'][0]['answers'],['Réponse'])
 def test_11_failed_file_copy_rolls_back_records_and_created_bytes(self):
  first=self.ok(self.admin.upload('upload','One.txt',b'First bytes','text/plain'))['file'];missing=self.ok(self.admin.upload('upload','Two.txt',b'Missing original','text/plain'))['file']
  folder=h.Integration.install/'storage/files'
  for path in folder.iterdir():
   if path.read_bytes()==b'Missing original':path.unlink()
  before=set(folder.iterdir());count=len(self.ok(self.admin.api('files'))['files']);target=self.page('Destination conservée')
  blocks=[{'type':'fileBlock','attrs':{'fileId':f['id'],'mode':'download'}} for f in [first,missing]]
  self.ok(self.paste(target,blocks),409);self.assertEqual(set(folder.iterdir()),before);self.assertEqual(len(self.ok(self.admin.api('files'))['files']),count);self.assertEqual(self.current(target),target)
if __name__=='__main__':unittest.main(argv=[__file__]+h.REMAINING,verbosity=2)
